import { useRef } from 'react';

import { MouseCoordinate } from '../../../../core/types/overlays.js';
import { usePinnedTooltipState } from '../../../hooks/store/selectors.js';
import { useHistogramFilteredData } from '../../../hooks/useHistogramFilteredData.js';
import { useHistogramXScale } from '../../../hooks/useHistogramXScale.js';
import { useHistogramYScales } from '../../../hooks/useHistogramYScales.js';
import { HistogramDataPoint } from '../HistogramExplore/HistogramExploreOverlay.js';
import { getClosestBins, findClosestBinX } from '../utils/find-closest-bins.js';

export function useClosestBinsByMouse(mousePosition?: MouseCoordinate) {
  const pinnedTooltip = usePinnedTooltipState();
  const { xScale } = useHistogramXScale();
  const yScales = useHistogramYScales();
  const { series, binsMap, seriesMap } = useHistogramFilteredData();

  const closestBinsRef = useRef<HistogramDataPoint[]>([]);
  const closestBinRef = useRef<HistogramDataPoint | undefined>();
  const closestGroupedBinsRef = useRef<HistogramDataPoint[][]>([[]]);

  if (!pinnedTooltip && mousePosition) {
    const mouseX = xScale.invert(mousePosition.x);

    const closestBinsX = findClosestBinX(
      mouseX,
      series,
      yScales,
      xScale,
      seriesMap,
      binsMap,
    );

    const { closestBin, closestBinsByClosestOne, closestBinsGrouped } =
      getClosestBins(mousePosition.y, closestBinsX);

    closestBinRef.current = closestBin;
    closestBinsRef.current = closestBinsByClosestOne;
    closestGroupedBinsRef.current = closestBinsGrouped;
  }

  return {
    closestBin: closestBinRef.current,
    closestBins: closestBinsRef.current,
    closestGroupedBins: closestGroupedBinsRef.current,
  };
}
